<script setup lang="ts">import {ref,onMounted} from 'vue';import {api} from '../../api';import {t} from '../../locales';import '../../styles/app.scss';const rows=ref<any[]>([]);onMounted(async()=>rows.value=await api.messages());async function open(row:any){await api.markMessageRead(row.id);row.read=true;if(row.type==='news')uni.navigateTo({url:'/pages/detail/news?id='+row.target});else if(row.type==='point')uni.navigateTo({url:'/pages/detail/point?id='+row.target})}async function readAll(){await api.markAllMessagesRead();rows.value.forEach(x=>x.read=true);uni.showToast({title:t('已全部读'),icon:'none'})}</script>
<template><view class="inner-page"><view class="inner-nav"><text class="back" @click="uni.navigateBack()">‹</text><text class="nav-title">{{t('消息')}}</text><text class="nav-action" @click="readAll">{{t('全部已读')}}</text></view><view class="inner-main"><view v-if="!rows.length" class="inner-card empty-state">{{t('暂无消息')}}</view><view v-for="row in rows" :key="row.id" class="message-card" :class="{unread:!row.read}" @click="open(row)"><view class="message-icon">{{row.type==='news'?'▤':row.type==='point'?'⌁':'ⓘ'}}</view><view class="list-copy"><view class="message-head"><text class="list-title">{{row.title}}</text><text class="list-meta">{{row.time}}</text></view><text class="message-summary">{{row.summary}}</text></view><text v-if="!row.read" class="unread-dot">●</text></view></view></view></template><style scoped>.nav-action{margin-left:auto;color:var(--cf-brand);font-size:18rpx;font-weight:600}.message-card{display:flex;align-items:flex-start;gap:13rpx;padding:18rpx;background:#fff;border:1rpx solid var(--cf-line);border-radius:13rpx}.message-card+.message-card{margin-top:12rpx}.message-icon{display:grid;place-items:center;flex:0 0 42rpx;width:42rpx;height:42rpx;border-radius:11rpx;background:#EFF6FF;color:var(--cf-brand);font-size:23rpx}.message-head{display:flex;align-items:center;justify-content:space-between;gap:10rpx}.message-summary{display:block;margin-top:8rpx;color:var(--cf-muted);font-size:18rpx}.unread-dot{color:var(--cf-brand);font-size:15rpx}</style>
